(3786855, 534689, 19831, '<td valign="top">Your editing here is very nice. I really like the tones you''ve got.</td>', 'Your editing here is very nice. I really like the tones you''ve got.', '2007-06-15 01:30:22.000000', NULL, 1),
(3786866, 534663, 19831, '<td valign="top">An interesting idea. It seems like very harsh light, like onboard flash. Usually, one can get much more control, and flattering lighting either using available natural light, or controlled lighting, like studio lights, work lights or even smart use of household lamps, lights and such. Photography is all about light. There are some great tutorials on the site about lighting.</td>', 'An interesting idea. It seems like very harsh light, like onboard flash. Usually, one can get much more control, and flattering lighting either using available natural light, or controlled lighting, like studio lights, work lights or even smart use of household lamps, lights and such. Photography is all about light. There are some great tutorials on the site about lighting.', '2007-06-15 01:33:35.000000', NULL, 1),
(3786992, 532884, 19831, '<td valign="top">Your lighting here is absolutely wonderful!</td>', 'Your lighting here is absolutely wonderful!', '2007-06-15 02:21:12.000000', NULL, 1),
(3787004, 530859, 19831, '<td valign="top">Ah, this theme/concept has been widespread in this challenge, understandably. This is a very good conveyance of that idea. The choice of composition is good for this, no superflous elements, everything present serves the theme. A graphic look that I like, and seems to work well. My only minor nitpick, is the hands look a little flat, contrast wise. I wonder if a little different levels or curves tweaking could add a wee punch? A good photo, I like it for this challenge. :-)</td>', 'Ah, this theme/concept has been widespread in this challenge, understandably. This is a very good conveyance of that idea. The choice of composition is good for this, no superflous elements, everything present serves the theme. A graphic look that I like, and seems to work well. My only minor nitpick, is the hands look a little flat, contrast wise. I wonder if a little different levels or curves tweaking could add a wee punch? A good photo, I like it for this challenge. :-)', '2007-06-15 02:31:55.000000', NULL, 1),
(3787041, 534350, 61863, '<td valign="top">Glass is very dark IMO</td>', 'Glass is very dark IMO', '2007-06-15 03:05:47.000000', NULL, 1),
(3787045, 533662, 61863, '<td valign="top">Needs a bit more focus IMO</td>', 'Needs a bit more focus IMO', '2007-06-15 03:06:58.000000', NULL, 1),
(3787051, 534911, 61863, '<td valign="top">Nice title</td>', 'Nice title', '2007-06-15 03:08:09.000000', NULL, 1),
(3787053, 533577, 61863, '<td valign="top">Highlights a bit overblown perhaps - nice idea</td>', 'Highlights a bit overblown perhaps - nice idea', '2007-06-15 03:09:11.000000', NULL, 1),
(3787072, 534775, 61863, '<td valign="top">Bit too much water obscuring the face IMO but great idea</td>', 'Bit too much water obscuring the face IMO but great idea', '2007-06-15 03:21:13.000000', NULL, 1),
(3787073, 535619, 61863, '<td valign="top">Nice clean picture</td>', 'Nice clean picture', '2007-06-15 03:22:06.000000', NULL, 1),
(3787075, 534152, 61863, '<td valign="top">Needs some focus IMO</td>', 'Needs some focus IMO', '2007-06-15 03:23:41.000000', NULL, 1),
(3787195, 534982, 79095, '<td valign="top">Nice concept - it expresses the challenge subject well. Perhaps a location that didn''t have the lights in the foreground would be better. Also,getting some more exposure into the foreground might make it pop as a transitional subject more - really highlight that change from light to dark.</td>', 'Nice concept - it expresses the challenge subject well. Perhaps a location that didn''t have the lights in the foreground would be better. Also,getting some more exposure into the foreground might make it pop as a transitional subject more - really highlight that change from light to dark.', '2007-06-15 04:47:40.000000', NULL, 1),
(3787196, 533634, 79095, '<td valign="top">This is a nice interpretation of the topic. Perhaps a different surface for the rings to sit on? As it is it plays with the eyes a bit.</td>', 'This is a nice interpretation of the topic. Perhaps a different surface for the rings to sit on? As it is it plays with the eyes a bit.', '2007-06-15 04:48:51.000000', NULL, 1),
(3787201, 534771, 79095, '<td valign="top">Love the title. Makes your artistic expression pop out. Nice.</td>', 'Love the title. Makes your artistic expression pop out. Nice.', '2007-06-15 04:51:24.000000', NULL, 1),
(3787205, 534896, 79095, '<td valign="top">This is a lovely photo. Not only did you capture the transitional point the boat is at but the ''transition'' from ligh, happy, boating to dark, ominous sky is brilliant. I really like this.</td>', 'This is a lovely photo. Not only did you capture the transitional point the boat is at but the ''transition'' from ligh, happy, boating to dark, ominous sky is brilliant. I really like this.', '2007-06-15 04:55:39.000000', NULL, 1),
(3787211, 534842, 79095, '<td valign="top">This picture tells a story - one that is up to the viewer to inhabit. I really like this interpretation of the topic.</td>', 'This picture tells a story - one that is up to the viewer to inhabit. I really like this interpretation of the topic.', '2007-06-15 04:58:17.000000', NULL, 1),
(3787214, 534564, 79095, '<td valign="top">This is a great interpretation of the topic. I love it as a statement. Perhaps somehwere with some more character in the foreground (bigger rocks or more gnarled ones) and possibly a slightly longer exposure to highlight the everlasting but gentle aspect of the transition at the shore here.</td>', 'This is a great interpretation of the topic. I love it as a statement. Perhaps somehwere with some more character in the foreground (bigger rocks or more gnarled ones) and possibly a slightly longer exposure to highlight the everlasting but gentle aspect of the transition at the shore here.', '2007-06-15 05:08:26.000000', NULL, 1),
(3787349, 533661, 35004, '<td valign="top">It''s funny, the last challenge of the same name was won by a very similar picture, except this one is much better in my opinion. The outline of the subject is so dark, against the summer sky, and the background of the skate park has plenty of interest, colour and most of all, dimension. Could be a ribbon-getter.</td>', 'It''s funny, the last challenge of the same name was won by a very similar picture, except this one is much better in my opinion. The outline of the subject is so dark, against the summer sky, and the background of the skate park has plenty of interest, colour and most of all, dimension. Could be a ribbon-getter.', '2007-06-15 07:30:48.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3787351, 534854, 35004, '<td valign="top">I have voted on 107 out of 305, and this one is the best so far! 8!<br/> <br/><i>edit. I have now voted on all pictures, and you are still in my top bracket!</i></td>', 'I have voted on 107 out of 305, and this one is the best so far! 8! edit. I have now voted on all pictures, and you are still in my top bracket!', '2007-06-15 07:31:54.000000', NULL, 1),
