(3787354, 531892, 35004, '<td valign="top">Beautiful image, so clean, and crisp. Great use of two contrasting colours.</td>', 'Beautiful image, so clean, and crisp. Great use of two contrasting colours.', '2007-06-15 07:34:20.000000', NULL, 1),
