(3787929, 531346, 79095, '<td valign="top">This is a nice concept, but I think you need to bring out the detail in the water in the foreground to make it pop.</td>', 'This is a nice concept, but I think you need to bring out the detail in the water in the foreground to make it pop.', '2007-06-15 11:15:28.000000', NULL, 1),
(3787938, 534543, 79095, '<td valign="top">Good idea, but I think a position that didn''t have that road in the foreground would yield a much stronger shot.</td>', 'Good idea, but I think a position that didn''t have that road in the foreground would yield a much stronger shot.', '2007-06-15 11:17:17.000000', NULL, 1),
(3787941, 534312, 79095, '<td valign="top">Very nice composition.</td>', 'Very nice composition.', '2007-06-15 11:18:04.000000', NULL, 1),
(3787950, 533875, 79095, '<td valign="top">This is really lovely. That you were able to capture the shafts of light really makes the picture - it gives a tangible sense of movement or change. The muted colours give it a brooding feel that works nicely.</td>', 'This is really lovely. That you were able to capture the shafts of light really makes the picture - it gives a tangible sense of movement or change. The muted colours give it a brooding feel that works nicely.', '2007-06-15 11:20:36.000000', NULL, 1),
(3787954, 534049, 79095, '<td valign="top">This is a classic but very nice shot. I really like the colours you were able to capture, and the way the land frames the sky is just perfect.</td>', 'This is a classic but very nice shot. I really like the colours you were able to capture, and the way the land frames the sky is just perfect.', '2007-06-15 11:21:51.000000', NULL, 1),
(3787960, 529940, 79095, '<td valign="top">This is a nice idea, but I think you need to have the boards align with the bottom frame and have you focus on the water with a very fast shutter speed to convey the turbulence (or a slow one for the opposite different mood).</td>', 'This is a nice idea, but I think you need to have the boards align with the bottom frame and have you focus on the water with a very fast shutter speed to convey the turbulence (or a slow one for the opposite different mood).', '2007-06-15 11:23:53.000000', NULL, 1),
(3787981, 534840, 79095, '<td valign="top">This is a lovely picture. The colours and patterns in the water effectively draw the eye to the horizon.</td>', 'This is a lovely picture. The colours and patterns in the water effectively draw the eye to the horizon.', '2007-06-15 11:28:56.000000', NULL, 1),
(3788020, 534986, 79095, '<td valign="top">This has a lovely ethereal feel to it. Perhaps a little less of the lit areas in the background would concentrate the focus on the transition layers and the thoughtfullness of the human subject (portrait layout rather than landscape?)?</td>', 'This has a lovely ethereal feel to it. Perhaps a little less of the lit areas in the background would concentrate the focus on the transition layers and the thoughtfullness of the human subject (portrait layout rather than landscape?)?', '2007-06-15 11:41:35.000000', NULL, 1),
(3788160, 529595, 42100, '<td valign="top">LOL, you either have a real good sport of a friend or came across one very strange dude.  Fun photo!</td>', 'LOL, you either have a real good sport of a friend or came across one very strange dude.  Fun photo!', '2007-06-15 12:11:20.000000', NULL, 1),
