INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3790231, 535015, 19831, '<td valign="top">This is a real good idea. The colors are good. I think this particular point of view is hurting the presentation though. The building in the background and the  dark oof branch that is in front of the lens seem to be quite distracting. And the heavy contrast between the branches up in the blue sky area and the sky is resulting in some bad ca (purple fringing). I would suggest moving around and trying to frame your shot so there are no distracting elements, try to make it so everything in the shot contributes to the theme. You could also try and get in closer, and fill the frame with your subject (the leaves).</td>', 'This is a real good idea. The colors are good. I think this particular point of view is hurting the presentation though. The building in the background and the  dark oof branch that is in front of the lens seem to be quite distracting. And the heavy contrast between the branches up in the blue sky area and the sky is resulting in some bad ca (purple fringing). I would suggest moving around and trying to frame your shot so there are no distracting elements, try to make it so everything in the shot contributes to the theme. You could also try and get in closer, and fill the frame with your subject (the leaves).', '2007-06-15 23:35:41.000000', NULL, 1),
(3790390, 534965, 80026, '<td valign="top">This is very clever, believable and well executed !  I love it !</td>', 'This is very clever, believable and well executed !  I love it !', '2007-06-16 00:35:29.000000', NULL, 1),
