(3793739, 534817, 64446, '<td valign="top">Great idea. The lighting could be improved - we can see many shadows all over her face.</td>', 'Great idea. The lighting could be improved - we can see many shadows all over her face.', '2007-06-17 13:26:14.000000', NULL, 1),
(3793748, 531892, 64446, '<td valign="top">Very creative and well composed.</td>', 'Very creative and well composed.', '2007-06-17 13:28:52.000000', NULL, 1),
(3793812, 533694, 67258, '<td valign="top">The concept is sound, and the composition is good.  For me, the photo is let down by the less than sharp focus, and the overly harsh lighting.</td>', 'The concept is sound, and the composition is good.  For me, the photo is let down by the less than sharp focus, and the overly harsh lighting.', '2007-06-17 14:07:03.000000', NULL, 1),
(3793823, 534564, 67258, '<td valign="top">The transition from land to sea? I am probably not sufficiently intellectual to understand this, but for me there are some problems with the photograph: the composition seems rather ''grabbed'', rather than considered, especially with the the division line falling so close to the centre.  I am not keen with the perspective point from which the photo has been taken and would have preferred a lower vantage point, although that may not have achieved the affect you were looking for...</td>', 'The transition from land to sea? I am probably not sufficiently intellectual to understand this, but for me there are some problems with the photograph: the composition seems rather ''grabbed'', rather than considered, especially with the the division line falling so close to the centre.  I am not keen with the perspective point from which the photo has been taken and would have preferred a lower vantage point, although that may not have achieved the affect you were looking for...', '2007-06-17 14:13:09.000000', NULL, 1),
(3793831, 534025, 67258, '<td valign="top">A superb candid - such a strong narrative can be built up around this photograph.</td>', 'A superb candid - such a strong narrative can be built up around this photograph.', '2007-06-17 14:17:26.000000', NULL, 1),
(3793856, 533608, 67258, '<td valign="top">LOL!</td>', 'LOL!', '2007-06-17 14:25:58.000000', NULL, 1),
(3793869, 534855, 67258, '<td valign="top">Slightly soft in the focus, but a lovely tender photograph.</td>', 'Slightly soft in the focus, but a lovely tender photograph.', '2007-06-17 14:31:12.000000', NULL, 1),
(3793872, 531805, 67258, '<td valign="top">Oh, very funny, and very good.</td>', 'Oh, very funny, and very good.', '2007-06-17 14:32:58.000000', NULL, 1),
