(3801691, 532123, 79832, '<td valign="top">Great contrast, tone and light</td>', 'Great contrast, tone and light', '2007-06-19 13:51:37.000000', NULL, 1),
(3801702, 533992, 51538, '<td valign="top">Maternity shots are an enigma to me.  Except for the fact that they are money-makers for photographers, that is.  But from the beauty point of view, I feel that they have nothing to offer.  As for the memories point of view, there is always the most important one - the child.  A big fat belly?  Beats me.  But as for the challenge, it is an apt choice since it does in its way show a transition. 6.</td>', 'Maternity shots are an enigma to me.  Except for the fact that they are money-makers for photographers, that is.  But from the beauty point of view, I feel that they have nothing to offer.  As for the memories point of view, there is always the most important one - the child.  A big fat belly?  Beats me.  But as for the challenge, it is an apt choice since it does in its way show a transition. 6.', '2007-06-19 13:55:23.000000', NULL, 1),
(3801715, 530914, 67258, '<td valign="top">Superb!  The detail in the texture of the newly fledged feathers is so clear, the focus spot on, and it is well composed too - very good work indeed.  And wrens are probably my favourite bird too!</td>', 'Superb!  The detail in the texture of the newly fledged feathers is so clear, the focus spot on, and it is well composed too - very good work indeed.  And wrens are probably my favourite bird too!', '2007-06-19 14:02:37.000000', NULL, 1),
(3801726, 534224, 51538, '<td valign="top">I guess that is a skinned black cat on the floor?</td>', 'I guess that is a skinned black cat on the floor?', '2007-06-19 14:05:06.000000', NULL, 1),
(3801801, 535244, 76409, '<td valign="top">Good pic and cute guys! Good job.</td>', 'Good pic and cute guys! Good job.', '2007-06-19 14:29:51.000000', NULL, 1),
(3801808, 530409, 51538, '<td valign="top">Perfect antidote for the eye strain I am having in grading this challenge.  Thank you. 9.</td>', 'Perfect antidote for the eye strain I am having in grading this challenge.  Thank you. 9.', '2007-06-19 14:32:18.000000', NULL, 1),
(3801810, 531892, 51538, '<td valign="top">Nice stock imagery.  Clever idea and well photographed. 9.</td>', 'Nice stock imagery.  Clever idea and well photographed. 9.', '2007-06-19 14:32:50.000000', NULL, 1),
(3801811, 535038, 51538, '<td valign="top">Title is well chosen and enhances.  But even without the title, I like the evocative story-telling aspect of your photo and the noise.  Works very well. 9.</td>', 'Title is well chosen and enhances.  But even without the title, I like the evocative story-telling aspect of your photo and the noise.  Works very well. 9.', '2007-06-19 14:32:53.000000', NULL, 1),
(3801812, 531847, 79832, '<td valign="top">Looks like an interesting setup but for some reason the focus looks soft.</td>', 'Looks like an interesting setup but for some reason the focus looks soft.', '2007-06-19 14:32:53.000000', NULL, 1),
