INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3888237, 531891, 35720, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by m_sarzynski:</b></div><hr/><i> I heard about making art in your latte cup a while back and tried for months to do it.  I failed miserably, but you seem to have the technique down!  Aside from that the beans against the white mug really appeal to me.  Overall a great job! </i></td></tr></table> <br/> <br/>Thanks for your comment. I wish I could do such artwork in the latte, but I can''t. My daughter works in a café and made this for me.</td>', 'Originally posted by m_sarzynski: I heard about making art in your latte cup a while back and tried for months to do it.  I failed miserably, but you seem to have the technique down!  Aside from that the beans against the white mug really appeal to me.  Overall a great job!   Thanks for your comment. I wish I could do such artwork in the latte, but I can''t. My daughter works in a café and made this for me.', '2007-07-10 07:19:31.000000', NULL, 0),
(3896793, 534970, 48228, '<td valign="top">Totally awesome, re the colors, idea, and composition.....</td>', 'Totally awesome, re the colors, idea, and composition.....', '2007-07-12 03:19:33.000000', NULL, 0),
(3900236, 533442, 30049, '<td valign="top">I was looking around at users that have the Sigma 10-20 lens for Minolta and noticed this shot on your profile page.  I opened it because I was curious as to what lens you used.  My guess was the Minolta 50mm Macro lens you have listed (the 100 is capable of this as well I suppose).  You didn''t select a lens in the photograph info section.  :/<br/> <br/>I''m very glad I opened this up to take a look.  WOW!  I love this image.  Quite fantastic with the stunning foreground and background bokeh!  Well seen and captured.  A bit surprised at the score, way underrated IMO.<br/> <br/>A new fav for me.  :)</td>', 'I was looking around at users that have the Sigma 10-20 lens for Minolta and noticed this shot on your profile page.  I opened it because I was curious as to what lens you used.  My guess was the Minolta 50mm Macro lens you have listed (the 100 is capable of this as well I suppose).  You didn''t select a lens in the photograph info section.  :/ I''m very glad I opened this up to take a look.  WOW!  I love this image.  Quite fantastic with the stunning foreground and background bokeh!  Well seen and captured.  A bit surprised at the score, way underrated IMO. A new fav for me.  :)', '2007-07-13 10:40:11.000000', NULL, 0),
(3904600, 535038, 63398, '<td valign="top">Gutsy and emotive. A very powerful image and story. Though title-driven to a certain extent, that''s not necessarily a bad thing. Vastly underrated.</td>', 'Gutsy and emotive. A very powerful image and story. Though title-driven to a certain extent, that''s not necessarily a bad thing. Vastly underrated.', '2007-07-15 08:34:17.000000', NULL, 0),
